    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();

        int width = Math.min(n, m);
        int height = Math.max(n, m);
        int states = 1 << width;
        int fullMask = states - 1;
        int inf = 1_000_000;

        int[] count = new int[states];
        int[] horizontalCover = new int[states];

        for (int mask = 0; mask < states; mask++) {
            count[mask] = Integer.bitCount(mask);
            horizontalCover[mask] =
                    mask | ((mask << 1) & fullMask) | (mask >>> 1);
        }

        int[][] dp = new int[states][states];
        for (int[] row : dp) Arrays.fill(row, inf);

        for (int firstRow = 0; firstRow < states; firstRow++) {
            dp[0][firstRow] = count[firstRow];
        }

        for (int row = 1; row < height; row++) {
            int[][] next = new int[states][states];
            for (int[] values : next) Arrays.fill(values, inf);

            for (int aboveAbove = 0; aboveAbove < states; aboveAbove++) {
                for (int above = 0; above < states; above++) {
                    int currentCost = dp[aboveAbove][above];
                    if (currentCost == inf) continue;

                    for (int current = 0; current < states; current++) {
                        if ((horizontalCover[above] | aboveAbove | current) != fullMask) {
                            continue;
                        }

                        int newCost = currentCost + count[current];
                        if (newCost < next[above][current]) {
                            next[above][current] = newCost;
                        }
                    }
                }
            }
            dp = next;
        }

        int minimumOccupied = inf;
        for (int above = 0; above < states; above++) {
            for (int last = 0; last < states; last++) {
                if ((horizontalCover[last] | above) == fullMask) {
                    minimumOccupied = Math.min(minimumOccupied, dp[above][last]);
                }
            }
        }

        System.out.println(n * m - minimumOccupied);
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();

        int rows = Math.max(n, m);
        int cols = Math.min(n, m);

        int maskCount = 1 << cols;
        int fullMask = maskCount - 1;
        int stateCount = 1 << (2 * cols);
        int inf = 1_000_000;

        int[] bitCount = new int[maskCount];
        int[] horizontalCoverage = new int[maskCount];

        for (int mask = 0; mask < maskCount; mask++) {
            bitCount[mask] = Integer.bitCount(mask);
            horizontalCoverage[mask] =
                    mask | (mask >>> 1) | ((mask << 1) & fullMask);
        }

        int[] dp = new int[stateCount];
        Arrays.fill(dp, inf);

        for (int first = 0; first < maskCount; first++) {
            dp[first] = bitCount[first];
        }

        for (int row = 1; row < rows; row++) {
            int[] next = new int[stateCount];
            Arrays.fill(next, inf);

            for (int state = 0; state < stateCount; state++) {
                if (dp[state] == inf) continue;

                int twoRowsBack = state >>> cols;
                int previous = state & fullMask;

                for (int current = 0; current < maskCount; current++) {
                    if ((horizontalCoverage[previous] |
                            twoRowsBack | current) != fullMask) {
                        continue;
                    }

                    int nextState = (previous << cols) | current;
                    int value = dp[state] + bitCount[current];
                    if (value < next[nextState]) {
                        next[nextState] = value;
                    }
                }
            }

            dp = next;
        }

        int minimumOccupied = inf;

        for (int state = 0; state < stateCount; state++) {
            if (dp[state] == inf) continue;

            int previous = state >>> cols;
            int last = state & fullMask;

            if ((horizontalCoverage[last] | previous) == fullMask) {
                minimumOccupied = Math.min(minimumOccupied, dp[state]);
            }
        }

        System.out.println(n * m - minimumOccupied);
    }

    private static class FastScanner {
        private final InputStream input;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = input.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        int width = Math.min(n, m);
        int height = Math.max(n, m);
        int states = 1 << width;
        int full = states - 1;
        int inf = 1_000_000;

        int[] bitCount = new int[states];
        int[] horizontalCoverage = new int[states];

        for (int mask = 0; mask < states; mask++) {
            bitCount[mask] = Integer.bitCount(mask);
            horizontalCoverage[mask] =
                    mask | ((mask << 1) & full) | (mask >>> 1);
        }

        int[] dp = new int[states * states];
        Arrays.fill(dp, inf);

        for (int firstRow = 0; firstRow < states; firstRow++) {
            dp[firstRow] = bitCount[firstRow];
        }

        for (int row = 1; row < height; row++) {
            int[] next = new int[states * states];
            Arrays.fill(next, inf);

            for (int previousPrevious = 0; previousPrevious < states; previousPrevious++) {
                int base = previousPrevious * states;

                for (int previous = 0; previous < states; previous++) {
                    int currentCost = dp[base + previous];
                    if (currentCost == inf) continue;

                    int missing = full & ~(previousPrevious | horizontalCoverage[previous]);
                    int optional = full ^ missing;

                    for (int subset = optional; ; subset = (subset - 1) & optional) {
                        int current = missing | subset;
                        int index = previous * states + current;
                        int newCost = currentCost + bitCount[current];

                        if (newCost < next[index]) {
                            next[index] = newCost;
                        }

                        if (subset == 0) break;
                    }
                }
            }

            dp = next;
        }

        int minimumOccupied = inf;

        for (int previousPrevious = 0; previousPrevious < states; previousPrevious++) {
            int base = previousPrevious * states;

            for (int last = 0; last < states; last++) {
                if ((previousPrevious | horizontalCoverage[last]) == full) {
                    minimumOccupied = Math.min(minimumOccupied, dp[base + last]);
                }
            }
        }

        System.out.println(n * m - minimumOccupied);
    }
}

