import java.io.*;
import java.util.*;

public class Main {
    private static final int INF = 1_000_000;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();

        int width = Math.min(n, m);
        int height = Math.max(n, m);
        int size = 1 << width;
        int full = size - 1;

        int[] bitCount = new int[size];
        int[] horizontal = new int[size];
        for (int mask = 0; mask < size; mask++) {
            bitCount[mask] = Integer.bitCount(mask);
            horizontal[mask] = mask | ((mask << 1) & full) | (mask >> 1);
        }

        int states = size * size;
        int[] dp = new int[states];
        Arrays.fill(dp, INF);

        for (int first = 0; first < size; first++) {
            dp[first] = bitCount[first];
        }

        for (int row = 1; row < height; row++) {
            int[] next = new int[states];
            Arrays.fill(next, INF);

            for (int state = 0; state < states; state++) {
                if (dp[state] == INF) continue;

                int twoRowsAbove = state >> width;
                int previous = state & full;
                int alreadyDominated = horizontal[previous] | twoRowsAbove;

                for (int current = 0; current < size; current++) {
                    if ((alreadyDominated | current) != full) continue;

                    int nextState = (previous << width) | current;
                    int value = dp[state] + bitCount[current];
                    if (value < next[nextState]) {
                        next[nextState] = value;
                    }
                }
            }
            dp = next;
        }

        int minimumOccupied = INF;
        for (int state = 0; state < states; state++) {
            if (dp[state] == INF) continue;

            int secondLast = state >> width;
            int last = state & full;
            if ((horizontal[last] | secondLast) == full) {
                minimumOccupied = Math.min(minimumOccupied, dp[state]);
            }
        }

        System.out.println(n * m - minimumOccupied);
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
